SELECT u.mobile as mobile
FROM b_openid_share as bos
INNER JOIN b_openid as bo ON bos.share_openid_id = bo.openid_id
LEFT JOIN b_user as u ON bo.user_id = u.user_id
WHERE (
bos.user_id IN

    #{id}

AND bos.flag = 1
AND bo.app_id = #{appid}
)

select count(1) AS new_user_count
from b_user
where (type = '社会客户' or type = '领导') AND flag != -1 AND create_time between #{startTime} and #{endTime}
